"""SST-2：补跑 Qwen3.5 9b 开思考的 cot（缺 16 条）和 role_cot（缺 32 条），从第一次的断点接着跑。

在终端运行：nohup python sst2_qwen9b_finish.py > sst2_qwen9b_finish.log 2>&1 &
结果写在当前目录的 sst2_qwen9b_finish/ 下；断线或停止后，重跑同一条命令会接着跑。
"""
import base64, hashlib, importlib.util, json, os, re, shutil, signal, subprocess, sys, time, types
import urllib.error, urllib.request, zipfile, zlib
from datetime import datetime, timezone
from pathlib import Path

EMBEDDED_ASSETS = {"sst2_instruction_eval.py": {"sha256": "c3c96be1fe1348be4a8075894bca3ee07a9cf1458048b260b4b700613d875a95", "bytes": 43601, "zlib_base64": ""}, "sst2_validation.tsv": {"sha256": "a7a3bfee7fc80566578791dfea290715934cc82f436c893361c4d0108a3554f8", "bytes": 99186, "zlib_base64": ""}, "sst2_validation.metadata.json": {"sha256": "d9c018c30511f87199684de5b848a8037e968412ec101db82677663228a4e1ef", "bytes": 566, "zlib_base64": ""}, "ollama_qwen3.5-9b_cot_think-on_n200_7bb4e18c58f6.jsonl": {"sha256": "e516a09f38b6569a2e95a82207ce139b5c619dad7deccc7a5a4210355d8b5c09", "bytes": 2532546, "zlib_base64": ""}, "ollama_qwen3.5-9b_role_cot_think-on_n200_1b58c504eaed.jsonl": {"sha256": "96d87f0fd35e734325b650b1536527dd05f136724adec806a623cffef4985d5b", "bytes": 2431038, "zlib_base64": ""}}

MODEL = "qwen3.5:9b"
EXPECTED_DIGEST = "56671c2ab9385f9cfcb404638e32cd62d88e3501d44822208363c010179a3c90"  # 第一次运行用的模型版本
OLLAMA_VERSION = "0.40.3"
CONTEXT_LENGTH = 8192
REQUEST_TIMEOUT = 1800
# 两组第一次分别在两个服务地址上运行；地址是实验指纹的一部分，沿用原地址才能接着断点跑
GROUPS = [("cot", "http://127.0.0.1:11434", "7bb4e18c58f6"), ("role_cot", "http://127.0.0.1:11435", "1b58c504eaed")]
REGISTRY = "https://registry.ollama.ai"

if Path("/kaggle/working").is_dir():
    ROOT, MODEL_DIR = Path("/kaggle/working/sst2_qwen9b_finish"), Path("/tmp/ollama_models")
else:
    ROOT, MODEL_DIR = Path.cwd() / "sst2_qwen9b_finish", Path.home() / "ollama_models"
META_DIR = ROOT / "metadata"
OUT = ROOT / "ollama_results" / f"qwen3.5-9b_{EXPECTED_DIGEST[:12]}"
for d in (ROOT, META_DIR, OUT, MODEL_DIR):
    d.mkdir(parents=True, exist_ok=True)
NOTES_PATH = META_DIR / "notes.json"
NOTES = json.loads(NOTES_PATH.read_text(encoding="utf-8")) if NOTES_PATH.exists() else []
SESSION = datetime.now(timezone.utc).strftime("%Y-%m-%d %H:%M UTC")
START = time.time()


def note(message):
    print(message, flush=True)
    NOTES.append({"session": SESSION, "minute": round((time.time() - START) / 60, 1), "message": message})
    NOTES_PATH.write_text(json.dumps(NOTES, ensure_ascii=False, indent=2), encoding="utf-8")


# 内置的评测脚本、数据和两组的断点（第一次跑到的 184 条、168 条）；断点文件已存在就不覆盖
for name, item in EMBEDDED_ASSETS.items():
    raw = zlib.decompress(base64.b64decode(item["zlib_base64"]))
    if len(raw) != item["bytes"] or hashlib.sha256(raw).hexdigest() != item["sha256"]:
        raise RuntimeError(f"内置文件 {name} 校验失败")
    target = OUT / name if name.endswith(".jsonl") else ROOT / name
    if not (name.endswith(".jsonl") and target.exists()):
        target.write_bytes(raw)
EVAL_SCRIPT, DATA = ROOT / "sst2_instruction_eval.py", ROOT / "sst2_validation.tsv"
spec = importlib.util.spec_from_file_location("sst2_instruction_eval", EVAL_SCRIPT)
EV = importlib.util.module_from_spec(spec)
spec.loader.exec_module(EV)
ROWS = EV.load_rows(types.SimpleNamespace(data_file=str(DATA), n=200))[0]
for prompt, url, fp in GROUPS:  # 设置和第一次完全一致，才会接着断点跑
    got = EV.experiment_fingerprint("ollama", MODEL, prompt, "on", url, EV.auto_max_tokens(prompt, "on"),
                                    EV.auto_temperature("on"), ROWS)[0]
    if got[:12] != fp:
        raise RuntimeError(f"{prompt} 的实验指纹对不上：{got[:12]} ≠ {fp}")
print("结果目录：", ROOT)

if not shutil.which("nvidia-smi") or subprocess.run(["nvidia-smi"], capture_output=True).returncode != 0:
    raise RuntimeError("没有 GPU")
smi = subprocess.run(["nvidia-smi"], capture_output=True, text=True).stdout
(META_DIR / "nvidia_smi_start.txt").write_text(smi, encoding="utf-8")
print(next((ln for ln in smi.splitlines() if "MiB" in ln or "Tesla" in ln or "NVIDIA" in ln), ""))

installed = subprocess.run(["ollama", "--version"], capture_output=True, text=True).stdout if shutil.which("ollama") else ""
if OLLAMA_VERSION not in installed:
    try:
        subprocess.run(["curl", "-fSL", "--retry", "3", "--connect-timeout", "30", "https://ollama.com/install.sh",
                        "-o", "/tmp/ollama_install.sh"], check=True)
        subprocess.run(["sh", "/tmp/ollama_install.sh"], env=dict(os.environ, OLLAMA_VERSION=OLLAMA_VERSION), check=True)
    except subprocess.CalledProcessError:
        if not installed:
            raise RuntimeError("下载 Ollama 失败，机器上也没有 Ollama")
        print(f"安装 Ollama {OLLAMA_VERSION} 失败，改用已有的版本：{installed.strip()}")
LOCAL = urllib.request.build_opener(urllib.request.ProxyHandler({}))


def api(url, endpoint, payload=None, timeout=10):
    body = None if payload is None else json.dumps(payload).encode("utf-8")
    req = urllib.request.Request(url + endpoint, data=body, headers={"Content-Type": "application/json"})
    with LOCAL.open(req, timeout=timeout) as response:
        return json.loads(response.read().decode("utf-8"))


def server_env(url):
    return dict(os.environ, OLLAMA_HOST=url.removeprefix("http://"), OLLAMA_MODELS=str(MODEL_DIR),
                OLLAMA_NUM_PARALLEL="1", OLLAMA_CONTEXT_LENGTH=str(CONTEXT_LENGTH), OLLAMA_KEEP_ALIVE="30m",
                OLLAMA_MAX_LOADED_MODELS="1", OLLAMA_NOPRUNE="1")


def start_server(url):
    """同一时间只开一个服务（一张卡放不下两份 9b），按这一组原来的地址启动。"""
    subprocess.run(["pkill", "-f", "ollama serve"], capture_output=True)
    time.sleep(3)
    log = (META_DIR / "ollama_server.log").open("a", encoding="utf-8")
    server = subprocess.Popen(["ollama", "serve"], env=server_env(url), stdout=log, stderr=subprocess.STDOUT,
                              start_new_session=True)
    deadline = time.monotonic() + 120
    while True:
        if server.poll() is not None:
            raise RuntimeError("Ollama 服务启动失败，见 metadata/ollama_server.log")
        try:
            version = api(url, "/api/version", timeout=2)["version"]
            break
        except (urllib.error.URLError, TimeoutError, OSError):
            if time.monotonic() > deadline:
                raise RuntimeError("等待 Ollama 服务超时")
            time.sleep(1)
    print(f"Ollama {version} 已在 {url} 就绪", flush=True)
    return version


def manual_pull(tag):
    """ollama pull 被拦时，用 curl 从同一个 registry 下载清单和文件，清单按原样保存（digest 不变）。"""
    name, _, ref = tag.partition(":")
    raw = subprocess.run(["curl", "-fsSL", "--retry", "3", "-H",
                          "Accept: application/vnd.docker.distribution.manifest.v2+json",
                          f"{REGISTRY}/v2/library/{name}/manifests/{ref or 'latest'}"],
                         capture_output=True, check=True, timeout=300).stdout
    manifest = json.loads(raw)
    (MODEL_DIR / "blobs").mkdir(parents=True, exist_ok=True)
    for layer in [manifest["config"]] + manifest["layers"]:
        path = MODEL_DIR / "blobs" / layer["digest"].replace(":", "-")
        if path.exists() and path.stat().st_size == layer["size"]:
            continue
        part = path.with_name(path.name + ".partial")
        print(f"  下载 {layer['digest'][:19]}…（{layer['size'] / 2 ** 30:.2f} GB）", flush=True)
        subprocess.run(["curl", "-fL", "--retry", "5", "--retry-delay", "5", "-C", "-", "-s", "-S", "-o", str(part),
                        f"{REGISTRY}/v2/library/{name}/blobs/{layer['digest']}"], check=True)
        sha = hashlib.sha256()
        with part.open("rb") as f:
            for chunk in iter(lambda: f.read(1 << 24), b""):
                sha.update(chunk)
        if "sha256:" + sha.hexdigest() != layer["digest"]:
            part.unlink()
            raise RuntimeError(f"{layer['digest']} 校验失败，已删除，重跑会重新下载")
        part.rename(path)
    target = MODEL_DIR / "manifests" / "registry.ollama.ai" / "library" / name / (ref or "latest")
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_bytes(raw)


def rows_in(prompt, fp):
    path = OUT / f"ollama_qwen3.5-9b_{prompt}_think-on_n200_{fp}.jsonl"
    done = set()
    if path.exists():
        for line in path.read_text(encoding="utf-8").splitlines():
            if line.strip():
                r = json.loads(line)
                if r.get("error") is None:
                    done.add(r["idx"])
    return len(done)


todo = []
for prompt, url, fp in GROUPS:
    n = rows_in(prompt, fp)
    print(f"9b {prompt} 开思考：已有 {n}/200 条" + ("，跳过" if n >= 200 else "，接着跑"))
    if n < 200:
        todo.append((prompt, url, fp))

version = start_server(GROUPS[0][1])
if todo:
    started = time.monotonic()
    result = subprocess.run(["ollama", "pull", MODEL], env=server_env(GROUPS[0][1]), capture_output=True, text=True,
                            timeout=3600)
    if result.returncode != 0:
        note(f"{MODEL}：ollama pull 失败（{' '.join((result.stdout + result.stderr).split())[-160:]}），改用 curl 直接下载")
        manual_pull(MODEL)
    entry = next((m for m in api(GROUPS[0][1], "/api/tags")["models"] if MODEL in (m.get("name"), m.get("model"))), None)
    digest = (entry or {}).get("digest", "").removeprefix("sha256:")
    if digest != EXPECTED_DIGEST:
        raise RuntimeError(f"模型版本和第一次不同（第一次 {EXPECTED_DIGEST[:12]}，这次 {digest[:12] or '没找到'}），"
                           "接着跑会混进不同的模型，先停下，把这条信息发给 Claude")
    (META_DIR / "model_qwen3.5-9b.json").write_text(json.dumps(
        {"tag": MODEL, "digest": digest, "tag_entry": entry, "ollama_version": version,
         "pull_seconds": round(time.monotonic() - started)}, ensure_ascii=False, indent=2), encoding="utf-8")
    note(f"{MODEL}：模型版本与第一次相同（{digest[:12]}），下载 {time.monotonic() - started:.0f} 秒")

for prompt, url, fp in todo:
    if url != GROUPS[0][1]:
        start_server(url)
    command = [sys.executable, str(EVAL_SCRIPT), "--provider", "ollama", "--base-url", url, "--model", MODEL,
               "--prompt", prompt, "--think", "on", "--data-file", str(DATA), "--workers", "1",
               "--timeout", str(REQUEST_TIMEOUT), "--out-dir", str(OUT), "--n", "200"]
    begin = time.monotonic()
    process = subprocess.Popen(command, cwd=ROOT, env=server_env(url), stdout=subprocess.PIPE,
                               stderr=subprocess.STDOUT, text=True, encoding="utf-8", errors="replace", bufsize=1,
                               start_new_session=True)
    try:
        with (OUT / f"{prompt}_think-on_n200_console.log").open("a", encoding="utf-8") as log:
            for line in process.stdout:
                print(line, end="", flush=True)
                log.write(line)
        process.wait()
    except KeyboardInterrupt:
        os.killpg(process.pid, signal.SIGINT)
        process.wait(timeout=60)
        note(f"9b {prompt} 开思考：手动停止，已完成的条目存在断点里")
        raise
    note(f"9b {prompt} 开思考：结束（返回码 {process.returncode}），用时 {(time.monotonic() - begin) / 60:.1f} 分钟，"
         f"现在 {rows_in(prompt, fp)}/200 条")
subprocess.run(["pkill", "-f", "ollama serve"], capture_output=True)

print(f"{'组':<16}{'已跑/目标':>10}{'正确':>6}{'准确率':>9}{'无效':>5}{'截断':>5}")
for prompt, url, fp in GROUPS:
    path = OUT / f"ollama_qwen3.5-9b_{prompt}_think-on_n200_{fp}.jsonl"
    recs = {}
    for line in path.read_text(encoding="utf-8").splitlines():
        if line.strip():
            r = json.loads(line)
            if r.get("error") is None:
                recs[r["idx"]] = r
    preds = [EV.parse_label(r["content"])[0] for r in recs.values()]
    correct = sum(p == r["label"] for p, r in zip(preds, recs.values()))
    print(f"{prompt + ' 开思考':<16}{f'{len(recs)}/200':>10}{correct:>6}{correct / len(recs):>9.2%}"
          f"{sum(p is None for p in preds):>5}{sum(r.get('finish') == 'length' for r in recs.values()):>5}")
try:
    (META_DIR / "nvidia_smi_end.txt").write_text(subprocess.run(["nvidia-smi"], capture_output=True, text=True).stdout,
                                                 encoding="utf-8")
except OSError:
    pass
ZIP_PATH = ROOT.parent / f"sst2_qwen9b_finish_results_{datetime.now(timezone.utc).strftime('%Y%m%d-%H%M')}.zip"
with zipfile.ZipFile(ZIP_PATH, "w", compression=zipfile.ZIP_DEFLATED) as archive:
    for path in sorted(p for p in ROOT.rglob("*") if p.is_file() and p.suffix in {".json", ".jsonl", ".csv", ".txt", ".log"}):
        archive.write(path, arcname="sst2_qwen9b_finish/" + path.relative_to(ROOT).as_posix())
print(f"结果包已保存：{ZIP_PATH}（{ZIP_PATH.stat().st_size / 2 ** 20:.1f} MB）。还需要你做的：下载这个文件，发给 Claude。")
